    m1points.add(3 * Core.m1weight);
}

@Test
public void practice_numDirectedTriangles_completeLargeAL() {
    int size = 150;
    int numTris = size * (size - 1) * (size - 2) / 3;
    HashSet<Integer> keys = new HashSet<Integer>();
    for (Integer i = 0; i < size; i++) {
        keys.add(i);
    }
    Graph<Integer> g = new AdjacencyListGraph<Integer>(keys);
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
            g.addEdge(i, j);
            g.addEdge(j, i);
        }
    }
    long startTime = System.nanoTime();
    assertEquals(numTris, g.numDirectedTriangles());
    long endTime = System.nanoTime();
    String timeInMs = Long.toString((endTime - startTime) / 1000000);
    assertTrue(endTime - startTime <= 1000000000, timeInMs + " ms > 1000 ms is too slow");
    m1points.add(2 * Core.m1weight);
}
